B.bao=new A.aB("sfx_t14_lamp_flicker",0.001,1,null,1)
B.afv=s([B.bao],t.e)
B.bof=new A.h9("N\u011bkdy se mus\xed\u0161 o kousek vr\xe1tit, a\u0165 se dostane\u0161 d\xe1l.","P\u0159elij ze zvednut\xe9 n\xe1doby do t\xe9, kter\xe1 sv\xedt\xed. Cesta dop\u0159edu n\u011bkdy vede kousek zp\xe1tky.")
B.afw=s([B.bof],t.AE)
B.a3j=new A.k(0.7019607843137254,1,0.8784313725490196,0.5490196078431373,B.d)
B.a3g=new A.k(0.25098039215686274,1,0.8784313725490196,0.5490196078431373,B.d)
B.a_8=new A.k(0,1,0.8784313725490196,0.5490196078431373,B.d)
B.afx=s([B.a3j,B.a3g,B.a_8],t.W)
B.awW=new A.aO("Je \u010dtvrtek odpoledne a t\u0159\xedda je na v\xfdlet\u011b v muzeu. Vstupn\xed hala je pln\xe1 d\u011bt\xed. Dupou po schodech, \u0161eptaj\xed si a sm\u011bj\xed se. Ema, Jon\xe1\u0161, Nela a ty se zastav\xedte u velk\xe9ho obrazu u hlavn\xedch dve\u0159\xed. Je na n\u011bm vzne\u0161en\xe1 d\xe1ma v \u0161atech, kter\xe1 sp\xed. A tv\xe1\u0159\xed se p\u011bkn\u011b nerudn\u011b.")
B.aM=new A.kh("ema","assets/images/stories/museum/story/portrait_ema.webp")
B.ahm=s(["\u201e\u201aBaronka Frida von\u2026 Schla\u2026 Scho\u2026 Schovanburger.\u2018 Schovan\xfd burger? Kter\xfd bl\xe1zen by schov\xe1val burger?\u201c"],t.s)
B.biO=new A.a6(B.aM,B.ahm,!1)
B.aS=new A.kh("jonas","assets/images/stories/museum/story/portrait_jonas.webp")
B.agB=s(["\u201eSchlafenberg, Emo. \u017d\xe1dn\xfd schovan\xfd burger. Schlafen je n\u011bmecky sp\xe1t a Berg je hora. Kdy\u017e si to p\u0159elo\u017e\xed\u0161, tak je to Baronka ze Spac\xed hory.\u201c"],t.s)
B.bjc=new A.a6(B.aS,B.agB,!1)
B.aY=new A.kh("nela","assets/images/stories/museum/story/portrait_nela.webp")
B.anB=s(["\u201eTak to se na t\xe9 ho\u0159e asi moc dob\u0159e nesp\xed. Vypad\xe1, \u017ee nespala celou v\u011b\u010dnost.\u201c"],t.s)
B.bjN=new A.a6(B.aY,B.anB,!1)
B.axj=new A.aO("Pod jm\xe9nem baronky vis\xed je\u0161t\u011b jedna men\u0161\xed cedulka.")
B.ae1=s(["\u201e\u201aZ\xedtra r\xe1no se obraz st\u011bhuje do nov\xe9 galerie na hlavn\xedm n\xe1dra\u017e\xed.\u2018\u201c"],t.s)
B.bld=new A.a6(B.aM,B.ae1,!1)
B.axk=new A.aO("Jon\xe1\u0161 by p\u0159\xedsahal, \u017ee se baronka v tu chv\xedli zamra\u010dila je\u0161t\u011b v\xedc.")
B.aoi=s([B.awW,B.biO,B.bjc,B.bjN,B.axj,B.bld,B.axk],t.a)
B.bmR=new A.cl("story_01",B.aoi)
B.aww=new A.aO("Kdy\u017e exkurze skon\u010d\xed, v\u0161ichni sp\u011bchaj\xed k autobusu. Teda t\xe9m\u011b\u0159 v\u0161ichni.")
B.ahU=s(["\u201ePsst. M\xe1m pl\xe1n. Schov\xe1me se v \u0161atn\u011b a muzeum bude v noci jen na\u0161e.\u201c"],t.s)
B.biv=new A.a6(B.aM,B.ahU,!1)
B.ag5=s(["\u201eTo je ten nejhor\u0161\xed pl\xe1n, jak\xfd jsem kdy sly\u0161el.\u201c"],t.s)
B.biu=new A.a6(B.aS,B.ag5,!1)
B.awi=new A.aO("Autobus odjede. Muzeum se zav\u0159e a sv\u011btla zhasnou. V\u0161echny hodiny v muzeu se v tu chv\xedli zastav\xed a ru\u010di\u010dky sko\u010d\xed na p\u016flnoc.")
B.anH=s(["\u201eZavol\xe1m dom\u016f, \u017ee se exkurze trochu prot\xe1hne. Hm. Nem\xe1m sign\xe1l, ani \u010d\xe1rku.\u201c"],t.s)
B.bk7=new A.a6(B.aY,B.anH,!1)
B.agx=s(["\u201eA vstupn\xed dve\u0159e jsou zam\u010den\xe9! Jako by n\xe1s muzeum necht\u011blo pustit ven.\u201c"],t.s)
B.bin=new A.a6(B.aS,B.agx,!1)
B.awo=new A.aO("A d\u011bti poprv\xe9 napadne, \u017ee se odsud mo\u017en\xe1 nedostanou. Ani dnes. Ani nikdy.")
B.abs=s(["\u201eTak nebudeme \u010dekat. Prozkoum\xe1me to tu. Jenom pot\u0159ebujeme sv\u011btlo.\u201c"],t.s)
B.blD=new A.a6(B.aM,B.abs,!1)
B.awu=new A.aO("V muzeu je prapodivn\xe9 ticho. V \u0161atn\u011b na zdi nejist\u011b blik\xe1 lampa. Nela najde u dve\u0159\xed star\xfd oto\u010dn\xfd vyp\xedna\u010d a zku\u0161en\u011b s n\xedm p\xe1rkr\xe1t cvakne. Lampa zaprask\xe1, zablik\xe1 a rozsv\xedt\xed se naplno.")
B.afN=s([B.aww,B.biv,B.biu,B.awi,B.bk7,B.bin,B.awo,B.blD,B.awu],t.a)
B.bmK=new A.cl("story_02",B.afN)
B.awY=new A.aO("Posledn\xed sk\u0159\xed\u0148ka se s vrznut\xedm otev\u0159e a na zem vypadne sto\u010den\xfd svitek. Je to pl\xe1nek muzea, nakreslen\xfd rukou. Na druh\xe9 stran\u011b je n\u011bco naps\xe1no rozt\u0159esen\xfdm p\xedsmem.")
B.afd=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d. Nev\u011b\u0159te jej\xedmu \xfasm\u011bvu. V. T.\u2018\u201c"],t.s)
B.blb=new A.a6(B.aS,B.afd,!1)
B.akX=s(["\u201eKdo je V. T.? A jak\xe9mu \xfasm\u011bvu?\u201c"],t.s)
B.bjf=new A.a6(B.aM,B.akX,!1)
B.amR=s(["\u201eSuper. Jsme zam\u010den\xed v muzeu a dost\xe1v\xe1me podivn\xe9 vzkazy. U\u017e tu chyb\xed jen stra\u0161idlo.\u201c"],t.s)
B.bl6=new A.a6(B.aY,B.amR,!1)
B.awk=new A.aO("Z chodby se ozve tich\xe9 \u0161ust\u011bn\xed dlouh\xfdch sukn\xed. A pak ospal\xfd \u0161epot, tak tich\xfd, \u017ee to mohl b\xfdt i pr\u016fvan:")
B.xd=new A.kh("baroness","assets/images/stories/museum/story/portrait_baroness.webp")
B.aoV=s(["\u201eRuhe\u2026\u201c"],t.s)
B.bj1=new A.a6(B.xd,B.aoV,!0)
B.agw=s(["\u201eTo je n\u011bmecky. Znamen\xe1 to\u2026 ticho.\u201c"],t.s)
B.blU=new A.a6(B.aS,B.agw,!1)
B.ax9=new A.aO("V\u0161em se zatajuje dech, proto\u017ee ta chodba je pr\xe1zdn\xe1.")
B.axa=new A.aO("D\u011bti rychle rozlo\u017e\xed pl\xe1nek na podlaze. Jen\u017ee tma na pap\xed\u0159e se pohne. P\u0159es chodby a s\xe1ly se pomalu val\xed \u010dern\xe1 mlha a schov\xe1v\xe1 cestu. Vid\u011bt je jen \u0161atna, kde pr\xe1v\u011b stoj\xed.")
B.aq3=s(["\u201eK \u010demu n\xe1m je zaml\u017een\xfd pl\xe1nek? Co s t\xedm chcete d\u011blat? Hr\xe1t na schov\xe1vanou?\u201c"],t.s)
B.bkZ=new A.a6(B.aY,B.aq3,!1)
B.ajY=s(["\u201eTen pl\xe1nek n\xe1s n\u011bkam vede. Tak jdeme zjistit kam.\u201c"],t.s)
B.bjq=new A.a6(B.aM,B.ajY,!1)
B.al9=s(["\u201eEmo, po\u010dkej\u2026 Emo!\u201c"],t.s)
B.bka=new A.a6(B.aS,B.al9,!1)
B.aoQ=s([B.awY,B.blb,B.bjf,B.bl6,B.awk,B.bj1,B.blU,B.ax9,B.axa,B.bkZ,B.bjq,B.bka],t.a)
B.bmY=new A.cl("story_03",B.aoQ)
B.axM=new A.aO("Posledn\xed dve\u0159e se otev\u0159ou a na pl\xe1nku se rozz\xe1\u0159\xed nakreslen\xe1 kost. D\u011bti stoj\xed p\u0159esn\u011b tam, kam je pl\xe1nek vedl, v s\xe1le dinosaur\u016f. Sv\xedt\xed tady jen jedna lampa. Uprost\u0159ed se ve tm\u011b r\xfdsuje n\u011bco obrovsk\xe9ho.")
B.aqd=s(["\u201eEmo\u2026 to obrovsk\xe9 cosi\u2026 se pr\xe1v\u011b pohnulo?\u201c"],t.s)
B.bl3=new A.a6(B.aS,B.aqd,!1)
B.axy=new A.aO("Ze tmy se ozve tich\xe9, dlouh\xe9, kostnat\xe9 zask\u0159\xedp\xe1n\xed.")
B.aea=s(["\u201e\u0158ekn\u011bte mi, \u017ee to byly dve\u0159e.\u201c"],t.s)
B.bix=new A.a6(B.aY,B.aea,!1)
B.agc=s([B.axM,B.bl3,B.axy,B.bix],t.a)
B.bmZ=new A.cl("story_04",B.agc)
B.awt=new A.aO("Posledn\xed kost zapadne na sv\xe9 m\xedsto. Kostra se zachv\u011bje, pomalu zvedne hlavu\u2026 a uk\xe1\u017ee \u010delist\xed k p\xedskovi\u0161ti v rohu s\xe1lu.")
B.akb=s(["\u201eEhm. D\u011bkujeme?\u201c"],t.s)
B.blR=new A.a6(B.aM,B.akb,!1)
B.acC=s(["\u201eRozum\xedm tomu spr\xe1vn\u011b, \u017ee n\xe1m pr\xe1v\u011b poradil dinosaurus?\u201c"],t.s)
B.biT=new A.a6(B.aY,B.acC,!1)
B.axh=new A.aO("P\xedskovi\u0161t\u011b ale vypad\xe1 \xfapln\u011b oby\u010dejn\u011b. Hromada p\xedsku a v n\xed\u2026 nic.")
B.aqs=s(["\u201e\u017d\xe1dn\xe1 cedulka. \u017d\xe1dn\xfd vzkaz. \u017d\xe1dn\xe1 \u0161ipka \u201aKl\xed\u010d je tady\u2018. To je teda pomoc.\u201c"],t.s)
B.bjs=new A.a6(B.aY,B.aqs,!1)
B.agE=s([B.awt,B.blR,B.biT,B.axh,B.bjs],t.a)
B.bnh=new A.cl("story_05",B.agE)
B.aw6=new A.aO("P\xedskovi\u0161t\u011b se ot\u0159ese, zadun\xed a p\xedsek vyst\u0159el\xed a\u017e ke stropu. Kdy\u017e se prach usad\xed, le\u017e\xed uprost\u0159ed kr\xe1teru zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm vyryt\xe1 kost. Jon\xe1\u0161 vyt\xe1hne vzkaz.")
B.apE=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d.\u2018 Jen\u017ee tohle nen\xed cel\xfd kl\xed\u010d. Je to jen kus!\u201c"],t.s)
B.bkP=new A.a6(B.aS,B.apE,!1)
B.ah2=s(["\u201eTak\u017ee zbytek bude schovan\xfd n\u011bkde jinde v muzeu.\u201c"],t.s)
B.bio=new A.a6(B.aY,B.ah2,!1)
B.avY=new A.aO("Lampa zablik\xe1 a zhasne. Ve tm\u011b se ozve dlouh\xe9, ospal\xe9 z\xedvnut\xed. Kdy\u017e se lampa znovu rozsv\xedt\xed, v s\xe1le nikdo nen\xed.")
B.alU=s(["\u201eKdo z v\xe1s to byl?\u201c"],t.s)
B.bij=new A.a6(B.aM,B.alU,!1)
B.aoE=s(["\u201eJ\xe1 ne!\u201c"],t.s)
B.bk0=new A.a6(B.aS,B.aoE,!1)
B.amQ=s([B.aw6,B.bkP,B.bio,B.avY,B.bij,B.bk0],t.a)
B.bnc=new A.cl("story_06",B.amQ)
B.ax1=new A.aO("D\u011bti doraz\xed do dal\u0161\xedho s\xe1lu. Je chladn\xfd a tajemn\u011b tich\xfd. Jde o egyptsk\xfd s\xe1l, je pln\xfd sarkof\xe1g\u016f, mumi\xed a soch d\xe1vn\xfdch boh\u016f. Mal\xfdm oknem pod stropem dopad\xe1 m\u011bs\xed\u010dn\xed sv\u011btlo.")
B.aiF=s(["\u201eTady n\u011bkde mo\u017en\xe1 bude dal\u0161\xed kus. Jen\u017ee kde?\u201c"],t.s)
B.biB=new A.a6(B.aS,B.aiF,!1)
B.axl=new A.aO("V rohu s\xe1lu le\u017e\xed v podlaze t\u011b\u017ek\xe1 kamenn\xe1 deska. Nehne se ani o milimetr. Ema se do n\xed op\u0159e celou vahou.")
B.al1=s(["\u201eJ\xe1 jsem v\u011bd\u011bla, \u017ee jsem m\u011bla r\xe1no sn\xedst ty dva rohl\xedky nav\xedc. \u201c"],t.s)
B.bjF=new A.a6(B.aM,B.al1,!1)
B.are=s([B.ax1,B.biB,B.axl,B.bjF],t.a)
B.bmU=new A.cl("story_07",B.are)
B.axi=new A.aO("M\u011bs\xed\u010dn\xed paprsek dopadne na vytesan\xfd symbol oka a ten se rozz\xe1\u0159\xed zlat\xfdm sv\u011btlem. K\xe1men zahu\u010d\xed, deska v rohu odjede stranou a odkryje schody. Vedou hluboko pod zem.")
B.add=s(["\u201eSchody do nezn\xe1ma. No jasn\u011b. Schody do cukr\xe1rny to asi nebudou, co?\u201c"],t.s)
B.bkW=new A.a6(B.aY,B.add,!1)
B.awS=new A.aO("Jon\xe1\u0161 se zastav\xed na prvn\xedm schodu. Nohy ho necht\u011bj\xed poslechnout. Nela mu str\u010d\xed do ruky baterku.")
B.aeO=s(["\u201eSpr\xe1vn\xfd gentleman jde p\u0159ece prvn\xed, ne?\u201c"],t.s)
B.bl8=new A.a6(B.aY,B.aeO,!1)
B.axc=new A.aO("Jon\xe1\u0161 se zhluboka nadechne.")
B.adw=s(["\u201eD-dob\u0159e. Jdu prvn\xed. Rychle, ne\u017e si to rozmysl\xedm.\u201c"],t.s)
B.bkx=new A.a6(B.aS,B.adw,!1)
B.abE=s([B.axi,B.bkW,B.awS,B.bl8,B.axc,B.bkx],t.a)
B.bmV=new A.cl("story_08",B.abE)
B.awN=new A.aO("Dole je hrobka. Je tu dusno, tma a ticho. Najednou to v\u0161ude zachrast\xed. Ze tmy vyb\u011bhnou drobn\xed brouci a rozprchnou se po cel\xe9 hrobce.")
B.amL=s(["\u201eFuj! Brouci! \u017div\xed brouci!\u201c"],t.s)
B.bkm=new A.a6(B.aS,B.amL,!1)
B.adT=s(["\u201eKlid, Jon\xe1\u0161i. Jsou to jen brouci.\u201c"],t.s)
B.blw=new A.a6(B.aM,B.adT,!1)
B.aev=s(["\u201eTo jsou skarabeov\xe9. Posv\xe1tn\xed brouci Egyp\u0165an\u016f. Ale je mi jedno, jak moc jsou posv\xe1tn\xed. Hlavn\u011b a\u0165 mi nelezou do bot.\u201c"],t.s)
B.bkk=new A.a6(B.aS,B.aev,!1)
B.amU=s(["\u201eJon\xe1\u0161i, te\u010f se neh\xfdbej. Jeden ti sed\xed na hlav\u011b.\u201c"],t.s)
B.blO=new A.a6(B.aY,B.amU,!1)
B.agK=s(["\u201eCo\u017ee?! Sundejte ho! Sundejte ho ze m\u011b!\u201c"],t.s)
B.bkN=new A.a6(B.aS,B.agK,!1)
B.aeh=s(["\u201eD\u011bl\xe1m si legraci.\u201c"],t.s)
B.bjb=new A.a6(B.aY,B.aeh,!1)
B.aiI=s([B.awN,B.bkm,B.blw,B.bkk,B.blO,B.bkN,B.bjb],t.a)
B.bmJ=new A.cl("story_09",B.aiI)
B.aw2=new A.aO("V\xedr v m\xedse se zpomal\xed, zastav\xed a zmiz\xed. T\u011b\u017ek\xe9 v\xedko se se sk\u0159\xedp\u011bn\xedm odsune stranou. Pod n\xedm vedou schody je\u0161t\u011b o n\u011bco hloub\u011bji.")
B.aff=s(["\u201eMuzeum m\xe1 v\xedc pater pod zem\xed ne\u017e nad n\xed. To n\xe1m nikdo na prohl\xeddce ne\u0159ekl. Asi pod\xe1m st\xed\u017enost.\u201c"],t.s)
B.bk2=new A.a6(B.aY,B.aff,!1)
B.axC=new A.aO("D\u011bti slezou dol\u016f a ocitnou se v mal\xe9m s\xe1le. \u017d\xe1dn\xe9 dve\u0159e. Nic. Jen k\xe1men a ticho.")
B.ahq=s(["\u201eNic tu nen\xed. Poj\u010fme rad\u0161i zp\xe1tky nahoru, dokud je\u0161t\u011b m\u016f\u017eeme.\u201c"],t.s)
B.bkr=new A.a6(B.aS,B.ahq,!1)
B.apZ=s(["\u201eNikam nejdeme. Tady n\u011bco mus\xed b\xfdt.\u201c"],t.s)
B.bky=new A.a6(B.aM,B.apZ,!1)
B.aid=s(["\u201eV pohod\u011b. Jsme jen hluboko pod zem\xed, v s\xe1le bez dve\u0159\xed, uprost\u0159ed noci, v muzeu, kter\xe9 n\xe1s nechce pustit. Co by se asi tak mohlo st\xe1t?\u201c"],t.s)
B.biW=new A.a6(B.aY,B.aid,!1)
B.ab6=s([B.aw2,B.bk2,B.axC,B.bkr,B.bky,B.biW],t.a)
B.bna=new A.cl("story_10",B.ab6)
B.axf=new A.aO("Pod prvn\xedm podstavcem se otev\u0159ou padac\xed dv\xed\u0159ka. Podstavec propadne do tmy a z jeho m\xedsta pomalu vystoup\xed zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm oko.")
B.aqP=s(["\u201eDal\u0161\xed kus!\u201c"],t.s)
B.bk1=new A.a6(B.aS,B.aqP,!1)
B.aeH=s(["\u201eVid\xedte? Pohoda. Tohle d\xe1me levou zadn\xed.\u201c"],t.s)
B.bj4=new A.a6(B.aM,B.aeH,!1)
B.aw3=new A.aO("D\u011bti vy\u0161plhaj\xed zp\xe1tky nahoru. Potom se odn\u011bkud z d\xe1lky ozve kovov\xe9 \u0159in\u010den\xed a slab\xfd, chraplav\xfd hlas:")
B.aC=new A.kh("clockmaker","assets/images/stories/museum/story/portrait_clockmaker.webp")
B.adk=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo? Pros\xedm v\xe1s\u2026 kolik je hodin?\u201c"],t.s)
B.blN=new A.a6(B.aC,B.adk,!0)
B.axz=new A.aO("Hlas jde z ryt\xed\u0159sk\xe9ho s\xe1lu. Vstupn\xed chodbu ale zav\xedr\xe1 t\u011b\u017ek\xe1 \u017eelezn\xe1 m\u0159\xed\u017e. Za m\u0159\xed\u017e\xed je tma a v t\xe9 tm\u011b n\u011bkdo je.")
B.alR=s(["\u201eKone\u010dn\u011b! Lid\xe9! Ne\u0159\xedkejte mi, \u017ee se mi jenom zd\xe1te.\u201c"],t.s)
B.blm=new A.a6(B.aC,B.alR,!0)
B.aoG=s(["\u201eKdo jste?\u201c"],t.s)
B.bl1=new A.a6(B.aM,B.aoG,!1)
B.adH=s(["\u201eTo je velmi dobr\xe1 ot\xe1zka. A\u017e na to p\u0159ijdu, \u0159eknu v\xe1m to.\u201c"],t.s)
B.blP=new A.a6(B.aC,B.adH,!0)
B.ax7=new A.aO("D\u011bti se chyt\xed m\u0159\xed\u017ee a zat\xe1hnou ze v\u0161ech sil. Tla\u010d\xed, lomcuj\xed s n\xed, ale m\u0159\xed\u017e se nehne ani o kousek.")
B.apl=s([B.axf,B.bk1,B.bj4,B.aw3,B.blN,B.axz,B.blm,B.bl1,B.blP,B.ax7],t.a)
B.bmF=new A.cl("story_11",B.apl)
B.ax5=new A.aO("M\u0159\xed\u017e s rachotem vyjede vzh\u016fru a v chodb\u011b se rozsv\xedt\xed. Na zemi tam sed\xed star\xfd mu\u017e v pracovn\xed z\xe1st\u011b\u0159e. Na nose m\xe1 br\xfdle, na \u010dele hodin\xe1\u0159skou lupu a ve vlasech pavu\u010dinu.")
B.agJ=s(["\u201eD\u011bkuji. Mnohokr\xe1t d\u011bkuji. Kolik je hodin?\u201c"],t.s)
B.biQ=new A.a6(B.aC,B.agJ,!1)
B.awT=new A.aO("Nela se pod\xedv\xe1 na mobil.")
B.am7=s(["\u201eNev\xedm. Mobily ukazuj\xed 00:00, vypad\xe1 to, \u017ee se zasekly.\u201c"],t.s)
B.bkI=new A.a6(B.aY,B.am7,!1)
B.aqt=s(["\u201ePo\u0159\xe1d p\u016flnoc? To je zvl\xe1\u0161tn\xed. Kdy\u017e mne sem n\u011bkdo zav\u0159el, zastavily se v\u0161echny hodiny p\u0159esn\u011b o p\u016flnoci. Bim, bam! Kukuk! Pardon. To se mi te\u010f n\u011bjak st\xe1v\xe1.\u201c"],t.s)
B.bl7=new A.a6(B.aC,B.aqt,!1)
B.awM=new A.aO("Jon\xe1\u0161 uk\xe1\u017ee na z\xe1st\u011bru.")
B.aj3=s(["\u201eTady m\xe1te jmenovku. \u201aMistr Vav\u0159inec Tikal, hodin\xe1\u0159 muzea.\u2018\u201c"],t.s)
B.bji=new A.a6(B.aS,B.aj3,!1)
B.amy=s(["\u201eVav\u0159inec Tikal! No jist\u011b, to jsem j\xe1! J\xe1 tu\u0161il, \u017ee m\xe1m n\u011bco spole\u010dn\xe9ho s hodinami.\u201c"],t.s)
B.biz=new A.a6(B.aC,B.amy,!1)
B.amn=s([B.ax5,B.biQ,B.awT,B.bkI,B.bl7,B.awM,B.bji,B.biz],t.a)
B.bn8=new A.cl("story_12",B.amn)
B.aqJ=s(["\u201eV. T.! To vy jste napsal ten vzkaz!\u201c"],t.s)
B.bj_=new A.a6(B.aM,B.aqJ,!1)
B.awp=new A.aO("Jon\xe1\u0161 mu uk\xe1\u017ee vzkaz ze \u0161atny. Hodin\xe1\u0159 zbledne.")
B.apU=s(["\u201eTo je opravdu moje p\xedsmo. Krasopis! Jedni\u010dka s hv\u011bzdi\u010dkou! Ale kdy bych to psal? A pro\u010d?\u201c"],t.s)
B.bkH=new A.a6(B.aC,B.apU,!1)
B.adK=s(["\u201eA kdo v\xe1s zav\u0159el?\u201c"],t.s)
B.bkV=new A.a6(B.aM,B.adK,!1)
B.aoZ=s(["\u201eJedna pan\xed. Byla kr\xe1sn\xe1, ale hrozn\u011b unaven\xe1. Nab\xeddla mi \u0161\xe1lek \u010daje a pak\u2026 u\u017e si nepamatuju nic, jen to, jak se usm\xedvala.\u201c"],t.s)
B.bj6=new A.a6(B.aC,B.aoZ,!1)
B.awb=new A.aO("V\u0161ichni se na sebe pod\xedvaj\xed. Nikdo nic ne\u0159ekne. Ale ka\u017ed\xfd mysl\xed na tot\xe9\u017e. Hodin\xe1\u0159 se zvedne, opr\xe1\u0161\xed si z\xe1st\u011bru a zam\xed\u0159\xed s nimi k hlavn\xedmu s\xe1lu. P\u0159ed n\xedm v\u0161ak jsou ryt\xed\u0159i v pln\xe9 zbroji. Stoj\xed bok po boku a nikoho nepust\xed d\xe1l.")
B.ahY=s(["\u201eAch, p\xe1nov\xe9 ryt\xed\u0159i. Velmi d\u016fstojn\xed. A velmi tvrdohlav\xed.\u201c"],t.s)
B.bll=new A.a6(B.aC,B.ahY,!1)
B.awI=new A.aO("Nela zaklepe na brn\u011bn\xed.")
B.ae2=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo?\u201c"],t.s)
B.biP=new A.a6(B.aY,B.ae2,!1)
B.awe=new A.aO("Brn\u011bn\xed dut\u011b zadun\xed. Ale \u017e\xe1dn\xfd z nich se ani nehne.")
B.ajD=s([B.bj_,B.awp,B.bkH,B.bkV,B.bj6,B.awb,B.bll,B.awI,B.biP,B.awe],t.a)
B.bmO=new A.cl("story_13",B.ajD)
B.awZ=new A.aO("Ryt\xed\u0159i jeden po druh\xe9m zasalutuj\xed a ustoup\xed stranou.")
B.aiT=s(["\u201eOni n\xe1m zasalutovali! Vid\u011bli jste to? Zasalutovali!\u201c"],t.s)
B.bju=new A.a6(B.aM,B.aiT,!1)
B.ar0=s(["\u201eRyt\xed\u0159sk\xe1 \u010dest. Pozor! Pohov! R\xe1z, dva, r\xe1z, dva! J\xe1 bych byl dobr\xfd ryt\xed\u0159. Jen by m\u011b ta zbroj tla\u010dila.\u201c"],t.s)
B.biN=new A.a6(B.aC,B.ar0,!1)
B.aed=s(["\u201eJe v po\u0159\xe1dku?\u201c"],t.s)
B.blT=new A.a6(B.aY,B.aed,!1)
B.ar9=s(["\u201eTen \u010daj byl asi hodn\u011b siln\xfd.\u201c"],t.s)
B.bkg=new A.a6(B.aS,B.ar9,!1)
B.aw_=new A.aO("V\u0161ichni pokra\u010duj\xed d\xe1l do obrovsk\xe9ho s\xe1lu. Je v n\u011bm \u0161ero a podlaha pod nohama zlov\u011bstn\u011b vr\u017ee.")
B.aii=s(["\u201eTuhle podlahu jsem\u2026 opravoval. Nebo jsem ji\u2026 hmm. Tady bych na va\u0161em m\xedst\u011b \u0161el opatrn\u011b. Nev\xedm pro\u010d. Ale \u0161el bych.\u201c"],t.s)
B.bku=new A.a6(B.aC,B.aii,!1)
B.af2=s(["\u201eTo je stra\u0161n\u011b uklid\u0148uj\xedc\xed.\u201c"],t.s)
B.bit=new A.a6(B.aY,B.af2,!1)
B.agf=s([B.awZ,B.bju,B.biN,B.blT,B.bkg,B.aw_,B.bku,B.bit],t.a)
B.bn1=new A.cl("story_14",B.agf)
B.awm=new A.aO("Deska se ot\u0159ese a pole se jedno po druh\xe9m propadaj\xed do tmy. K\u016f\u0148 stihne na posledn\xed chv\xedli odsko\u010dit do bezpe\u010d\xed. Z temn\xe9 j\xe1my vylet\xed zlat\xfd \xfalomek kl\xed\u010de se \u0161t\xedtem.")
B.ahe=s(["\u201eBum! To byla ale kr\xe1sa!\u201c"],t.s)
B.blW=new A.a6(B.aC,B.ahe,!1)
B.axs=new A.aO("V\u0161ichni se na n\u011bj pod\xedvaj\xed.")
B.acV=s(["\u201e\u2026Ehm. Pardon. Chci \u0159\xedct: to bylo velmi nebezpe\u010dn\xe9.\u201c"],t.s)
B.bjn=new A.a6(B.aC,B.acV,!1)
B.aoN=s(["\u201eA dal\u0161\xed kus.\u201c"],t.s)
B.bjo=new A.a6(B.aS,B.aoN,!1)
B.apB=s(["\u201eA kolik jich jako je\u0161t\u011b m\xe1 b\xfdt?\u201c"],t.s)
B.biR=new A.a6(B.aY,B.apB,!1)
B.axn=new A.aO("Hodin\xe1\u0159 prom\u011b\u0159uje \xfalomek lupou.")
B.aix=s(["\u201eKl\xed\u010d\u2026 To je moje pr\xe1ce. Tenhle kl\xed\u010d jsem kdysi vyrobil. Pro\u010d je ulomen\xfd? Kdo by\u2026 Ach ne.\u201c"],t.s)
B.bl9=new A.a6(B.aC,B.aix,!1)
B.aaP=s([B.awm,B.blW,B.axs,B.bjn,B.bjo,B.biR,B.axn,B.bl9],t.a)
B.bmN=new A.cl("story_15",B.aaP)
B.axK=new A.aO("Cesta k dal\u0161\xedmu s\xe1lu vede p\u0159es vstupn\xed halu. Kolem obrazu baronky proch\xe1zej\xed po \u0161pi\u010dk\xe1ch. Jon\xe1\u0161 se nechce d\xedvat, ale nakonec se stejn\u011b pod\xedv\xe1. Obraz je pr\xe1zdn\xfd. Z\u016fstalo jen osam\u011bl\xe9 k\u0159eslo.")
B.ap7=s(["\u201eKde je?\u201c"],t.s)
B.blH=new A.a6(B.aS,B.ap7,!1)
B.axq=new A.aO("Jon\xe1\u0161 mrkne. A baronka je zase zp\u011bt v obraze. Sp\xed a usm\xedv\xe1 se\u2026")
B.ajC=s(["\u201eTo je ona. Pan\xed baronka.\u201c"],t.s)
B.bk6=new A.a6(B.aC,B.ajC,!1)
B.aoM=s(["\u201eTo ona je ta pan\xed s \u010dajem? Ona v\xe1s zav\u0159ela?\u201c"],t.s)
B.bjl=new A.a6(B.aM,B.aoM,!1)
B.afj=s(["\u201eMo\u017en\xe1\u2026 Nev\xedm. Moje hlava je sam\xe1 d\xedra\u2026 jako ement\xe1l.\u201c"],t.s)
B.blG=new A.a6(B.aC,B.afj,!1)
B.afb=s(["\u201eAle vy jste p\u0159ece ten kl\xed\u010d vyrobil. Kdy\u017e si vzpomenete, zjist\xedme, kde je zbytek!\u201c"],t.s)
B.biS=new A.a6(B.aM,B.afb,!1)
B.aom=s(["\u201eAlchymista m\u011bl naho\u0159e ve v\u011b\u017ei svou laborato\u0159. On m\u011bl v\u017edycky l\xe9k na v\u0161echno.\u201c"],t.s)
B.bjk=new A.a6(B.aC,B.aom,!1)
B.ajk=s(["\u201eDob\u0159e, jdeme tam.\u201c"],t.s)
B.bjY=new A.a6(B.aM,B.ajk,!1)
B.ax_=new A.aO("Hodin\xe1\u0159 vede d\u011bti po to\u010dit\xfdch schodech nahoru do v\u011b\u017ee, do laborato\u0159e star\xe9ho alchymisty. V laborato\u0159i je ticho a v\u0161ude le\u017e\xed prach.")
B.ach=s(["\u201eTak, pane alchymisto. Kde m\xe1te ten l\xe9k na v\u0161echno?\u201c"],t.s)
B.bjp=new A.a6(B.aM,B.ach,!1)
B.adF=s([B.axK,B.blH,B.axq,B.bk6,B.bjl,B.blG,B.biS,B.bjk,B.bjY,B.ax_,B.bjp],t.a)
B.bnd=new A.cl("story_16",B.adF)
B.awD=new A.aO("V knize jsou t\u0159i recepty. Tenebrikus je lektvar no\u010dn\xedho vid\u011bn\xed. Ardeon je lektvar odvahy. A Siderion je elix\xedr hv\u011bzdn\xe9ho sv\u011btla. Pod n\xe1zvem je drobn\xe9 p\xedsmo.")
B.ahB=s(["\u201e\u201aRozjasn\xed mysl a vr\xe1t\xed ztracen\xe9 vzpom\xednky. Spr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch. Polovina d\xe1vky rozjasn\xed mysl. Cel\xe1 d\xe1vka usp\xed na sto let.\u2018\u201c"],t.s)
B.bla=new A.a6(B.aS,B.ahB,!1)
B.aw9=new A.aO("Kdy\u017e se obr\xe1t\xed posledn\xed list, le\u017e\xed na n\u011bm zlat\xfd \xfalomek kl\xed\u010de s hv\u011bzdou.")
B.aql=s(["\u201eDal\u0161\xed kus kl\xed\u010de! A k tomu recept na pam\u011b\u0165. Dneska m\xe1me \u0161\u0165astn\xfd den.\u201c"],t.s)
B.bk5=new A.a6(B.aM,B.aql,!1)
B.aod=s(["\u201eEmo, jsme zav\u0159en\xed v muzeu.\u201c"],t.s)
B.bjt=new A.a6(B.aY,B.aod,!1)
B.ahh=s(["\u201e\u0160\u0165astn\xfd den v r\xe1mci mo\u017enost\xed.\u201c"],t.s)
B.blA=new A.a6(B.aM,B.ahh,!1)
B.ane=s(["\u201e\u201aSpr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch.\u2018 Hv\u011bzdy ale odsud v\u016fbec nejsou vid\u011bt.\u201c"],t.s)
B.blc=new A.a6(B.aS,B.ane,!1)
B.awA=new A.aO("Nela uk\xe1\u017ee na \xfazk\xe9 sch\u016fdky v rohu.")
B.ako=s(["\u201eCo zkusit schody?\u201c"],t.s)
B.bkj=new A.a6(B.aY,B.ako,!1)
B.aw8=new A.aO("Sch\u016fdky vedou a\u017e na sam\xfd vrchol v\u011b\u017ee, do mal\xe9 hv\u011bzd\xe1rny. Za velk\xfdm oknem z\xe1\u0159\xed tis\xedce hv\u011bzd.")
B.ad5=s(["\u201eV\u017edy\u0165 je tu milion hv\u011bzd. Co s t\xedm m\xe1me d\u011blat?\u201c"],t.s)
B.bjd=new A.a6(B.aS,B.ad5,!1)
B.anj=s([B.awD,B.bla,B.aw9,B.bk5,B.bjt,B.blA,B.blc,B.awA,B.bkj,B.aw8,B.bjd],t.a)
B.bn2=new A.cl("story_17",B.anj)
B.axx=new A.aO("Souhv\u011bzd\xed na obloze se rozz\xe1\u0159\xed a do v\u011b\u017ee padne st\u0159\xedbrn\xe9 hv\u011bzdn\xe9 sv\u011btlo. Pomalu sklouzne po schodech dol\u016f, a\u017e do alchymistovy laborato\u0159e.")
B.abq=s(["\u201eTak\u017ee te\u010f asi ty hv\u011bzdy sv\xedt\xed spr\xe1vn\u011b. Kdo by \u0159ekl, \u017ee jdou hv\u011bzdy zapnout.\u201c"],t.s)
B.bli=new A.a6(B.aY,B.abq,!1)
B.awc=new A.aO("D\u011bti jdou za sv\u011btlem do laborato\u0159e.")
B.aj2=s(["\u201eMn\u011b se to tu nel\xedb\xed. N\u011bkdo n\xe1s tu nechce, c\xedt\xedm to.\u201c"],t.s)
B.bkb=new A.a6(B.aS,B.aj2,!1)
B.aeW=s(["\u201eAlchymista m\xedval v\u0161echno p\u0159ipraven\xe9 dop\u0159edu. Jestli ten l\xe9k n\u011bkde bude, tak ur\u010dit\u011b tady.\u201c"],t.s)
B.bkc=new A.a6(B.aC,B.aeW,!1)
B.ama=s([B.axx,B.bli,B.awc,B.bkb,B.bkc],t.a)
B.bng=new A.cl("story_18",B.ama)
B.awL=new A.aO("Hodin\xe1\u0159 vypije odm\u011b\u0159enou polovinu elix\xedru. \u0160kytne a v o\u010d\xedch mu zajisk\u0159\xed drobn\xe9 hv\u011bzdi\u010dky.")
B.amg=s(["\u201eLevandule! Ten \u010daj byl levandulov\xfd. A ona \u0159\xedkala: \u201aBu\u010fte tak laskav, mist\u0159e Tikale. Jenom zastavte hodiny. Jenom na chvilku.\u2018 Potom za\u0161eptala: \u201aJenom nav\u017edy.\u2018 Myslel jsem, \u017ee jsem \u0161patn\u011b rozum\u011bl. A pak\u2026 u\u017e si nic nepamatuju.\u201c"],t.s)
B.bkh=new A.a6(B.aC,B.amg,!1)
B.ajv=s(["\u201eJak\xe9 hodiny?\u201c"],t.s)
B.bk4=new A.a6(B.aS,B.ajv,!1)
B.agh=s(["\u201eTo je\u0161t\u011b nev\xedm. Ale v\xedm, kde to zjist\xedme.\u201c"],t.s)
B.biK=new A.a6(B.aC,B.agh,!1)
B.axD=new A.aO("Druhou polovinu elix\xedru hodin\xe1\u0159 pe\u010dliv\u011b zaz\xe1tkuje a schov\xe1 do kapsy z\xe1st\u011bry.")
B.aim=s(["\u201eNa hor\u0161\xed \u010dasy.\u201c"],t.s)
B.biE=new A.a6(B.aC,B.aim,!1)
B.axE=new A.aO("V tu chv\xedli se ze schodi\u0161t\u011b pod nimi oz\xfdv\xe1 tich\xe9 \u0161ust\u011bn\xed. Pomal\xfdmi kroky jde n\u011bkdo nahoru. V d\xe1lce se oz\xfdv\xe1 ospal\xfd hlas:")
B.amG=s(["\u201eWas ist das\u2026? Kdo m\u011b to zase ru\u0161\xed\u2026? Ruhe\u2026 Ruhe\u2026\u201c"],t.s)
B.bkR=new A.a6(B.xd,B.amG,!0)
B.aeG=s([B.awL,B.bkh,B.bk4,B.biK,B.axD,B.biE,B.axE,B.bkR],t.a)
B.bn6=new A.cl("story_19",B.aeG)
B.axA=new A.aO("Kroky se zastav\xed za dve\u0159mi a v\u0161ichni ztuhnou. Ozve se jen dlouh\xe9, ospal\xe9 z\xedvnut\xed. Pak \u0161ust\u011bn\xed sukn\xed pomalu sl\xe1bne, a\u017e utichne \xfapln\u011b.")
B.amm=s(["\u201eJe pry\u010d. Vr\xe1tila se do obrazu. O\u010dividn\u011b moc dlouho venku nevydr\u017e\xed.\u201c"],t.s)
B.biM=new A.a6(B.aS,B.amm,!1)
B.ahF=s(["\u201eTak toho vyu\u017eijeme. Rychle dol\u016f!\u201c"],t.s)
B.bkM=new A.a6(B.aM,B.ahF,!1)
B.awU=new A.aO("D\u011bti jdou tmou za hodin\xe1\u0159em. Vede je dlouhou chodbou a\u017e k n\xedzk\xfdm dve\u0159\xedm.")
B.afp=s(["\u201eMoje d\xedlna! Kdo mi tady ud\u011blal takov\xfd nepo\u0159\xe1dek? Aha. J\xe1. Tady b\xfdval v\u017edycky po\u0159\xe1dek. Ka\u017ed\xe9 hodiny v\u011bd\u011bly, kolik je hodin. Te\u010f nev\u011bd\xed nic. Ani jedny. Jako j\xe1.\u201c"],t.s)
B.biV=new A.a6(B.aC,B.afp,!1)
B.ao8=s([B.axA,B.biM,B.bkM,B.awU,B.biV],t.a)
B.bmX=new A.cl("story_20",B.ao8)
B.aw0=new A.aO("N\xe1st\u011bnn\xe9 hodiny odbij\xed p\u016flnoc a v\u0161echny bud\xedky se ozvou s nimi. Zvon\xed, cinkaj\xed a rachot\xed. Pak v\u0161echny zase ztichnou a ru\u010di\u010dky se znovu zastav\xed. A na podlaze pod pracovn\xedm stolem n\u011bco le\u017e\xed.")
B.aqO=s(["\u201eMoje bed\xfdnka! Moje sou\u010d\xe1stky! Pades\xe1t let jsem je t\u0159\xeddil!\u201c"],t.s)
B.bja=new A.a6(B.aC,B.aqO,!1)
B.ax0=new A.aO("Hodin\xe1\u0159 si k bed\xfdnce klekne a n\u011b\u017en\u011b ji hlad\xed.")
B.ag_=s(["\u201eTahle bed\xfdnka byla v\u017edycky na sv\xe9m m\xedst\u011b. A v\u0161echno v n\xed taky.\u201c"],t.s)
B.bjr=new A.a6(B.aC,B.ag_,!1)
B.akp=s([B.aw0,B.bja,B.ax0,B.bjr],t.a)
B.bni=new A.cl("story_21",B.akp)
B.awP=new A.aO("Posledn\xed sou\u010d\xe1stka zapadne na sv\xe9 m\xedsto a pod bed\xfdnkou se zaleskne zlat\xfd \xfalomek kl\xed\u010de s kole\u010dkem. Hodin\xe1\u0159 vezme bed\xfdnku do rukou. Chv\xedli se na ni d\xedv\xe1. A pak se mu v o\u010d\xedch rozsv\xedt\xed. Tentokr\xe1t doopravdy.")
B.aey=s(["\u201eU\u017e si vzpom\xedn\xe1m. Na v\u0161echno. Za orlojem je tajn\xe1 chodba, kter\xe1 vede k srdci muzea.\u201c"],t.s)
B.ble=new A.a6(B.aC,B.aey,!1)
B.arf=s(["\u201eBaronka m\u011b p\u0159inutila ho zastavit a zape\u010detit. Od t\xe9 chv\xedle je tu po\u0159\xe1d p\u016flnoc. R\xe1no nikdy nep\u0159ijde a dve\u0159e se nikdy neotev\u0159ou.\u201c"],t.s)
B.bik=new A.a6(B.aC,B.arf,!1)
B.aoH=s(["\u201eA kl\xed\u010d?\u201c"],t.s)
B.biD=new A.a6(B.aS,B.aoH,!1)
B.ah6=s(["\u201eTen rozlomila ona. Kousek po kousku roznesla \xfalomky po muzeu a u ka\u017ed\xe9ho nastra\u017eila past, aby u\u017e nikdo nemohl srdce muzea znovu probudit. A j\xe1 hlup\xe1k j\xed je\u0161t\u011b sv\xedtil na cestu.\u201c"],t.s)
B.bjL=new A.a6(B.aC,B.ah6,!1)
B.aaS=s(["\u201eJen jednou se mi na chv\xedli rozjasnilo v hlav\u011b. Rychle jsem napsal vzkaz a schoval ho do sk\u0159\xed\u0148ky v \u0161atn\u011b, kde by ho baronka nikdy nehledala. Stihl jsem to t\u011bsn\u011b p\u0159edt\xedm, ne\u017e mi poru\u010dila, a\u0165 se zav\u0159u za m\u0159\xed\u017e. A pak u\u017e jsem si nepamatoval nic.\u201c"],t.s)
B.bjA=new A.a6(B.aC,B.aaS,!1)
B.aqU=s(["\u201eAle pro\u010d to ud\u011blala?\u201c"],t.s)
B.bk_=new A.a6(B.aM,B.aqU,!1)
B.agg=s([B.awP,B.ble,B.bik,B.biD,B.bjL,B.bjA,B.bk_],t.a)
B.bnf=new A.cl("story_22",B.agg)
B.aoO=s(["\u201eZ\xedtra r\xe1no ji maj\xed odv\xe9zt do nov\xe9 galerie na n\xe1dra\u017e\xed. Mezi vlaky, hl\xe1\u0161en\xed a tis\xedce lid\xed. L\xe9ta tady nem\u016f\u017ee usnout kv\u016fli n\xe1v\u0161t\u011bvn\xedk\u016fm. A tam by neusnula u\u017e nikdy.\u201c"],t.s)
B.bjO=new A.a6(B.aC,B.aoO,!1)
B.aih=s(["\u201eTo je vlastn\u011b\u2026 trochu smutn\xe9.\u201c"],t.s)
B.biJ=new A.a6(B.aM,B.aih,!1)
B.aoy=s(["\u201eJen\u017ee j\xed je \xfapln\u011b jedno, \u017ee tu n\u011bkoho zamkne. A \u017ee se muzeum u\u017e nikdy neotev\u0159e. To je teda p\u011bkn\u011b sobeck\xe9.\u201c"],t.s)
B.bkX=new A.a6(B.aY,B.aoy,!1)
B.awF=new A.aO("Hodin\xe1\u0159 je zavede do rohu d\xedlny. Stoj\xed tam orloj, na kter\xe9m hodin\xe1\u0159 pracoval cel\xfd \u017eivot. Te\u010f ml\u010d\xed.")
B.ahQ=s(["\u201eMoje nejkr\xe1sn\u011bj\u0161\xed pr\xe1ce. A cesta k srdci muzea. Jen\u017ee jsem ho musel rozebrat.\u201c"],t.s)
B.biG=new A.a6(B.aC,B.ahQ,!1)
B.alW=s(["\u201eTak to oprav\xedme. Ur\u010dit\u011b to nebude t\u011b\u017ek\xe9.\u201c"],t.s)
B.bkT=new A.a6(B.aM,B.alW,!1)
B.afh=s(["\u201eTo sam\xe9 jsi \u0159\xedkala o tom pl\xe1nu se \u0161atnou. A pod\xedvej, kde jsme.\u201c"],t.s)
B.blI=new A.a6(B.aY,B.afh,!1)
B.ajx=s([B.bjO,B.biJ,B.bkX,B.awF,B.biG,B.bkT,B.blI],t.a)
B.bn0=new A.cl("story_23",B.ajx)
B.awC=new A.aO("Orloj se nadechne. Ru\u010di\u010dky se rozeb\u011bhnou a dv\xed\u0159ka dole se pomalu otev\u0159ou. Za nimi je \xfazk\xe1 chodba a na jej\xedm konci podivn\xe9 sv\u011btlo.")
B.apW=s(["\u201eTajn\xe1 chodba! Poj\u010fte!\u201c"],t.s)
B.bko=new A.a6(B.aM,B.apW,!1)
B.axr=new A.aO("Chodba za orlojem kon\u010d\xed ve skryt\xe9 hale s vysok\xfdm stropem. Uprost\u0159ed zdi vis\xed obrovsk\xe9 hodiny, p\u0159es cifern\xedk maj\xed rudou pe\u010de\u0165.")
B.anY=s(["\u201eSrdce muzea.\u201c"],t.s)
B.bkQ=new A.a6(B.aC,B.anY,!1)
B.awH=new A.aO("Za jejich z\xe1dy za\u0161ust\xed \u0161aty.")
B.axG=new A.aO("Ve dve\u0159\xedch haly stoj\xed baronka Frida von Schlafenberg. Skute\u010dn\xe1 a \u017eiv\xe1, vystoupila z obrazu. Je mnohem vy\u0161\u0161\xed, ne\u017e si mysleli. A hrozn\u011b, hrozn\u011b ospal\xe1.")
B.amh=s(["\u201eKinder\u2026 D\u011bti. Pro\u010d jste tak hlu\u010dn\xe9? Sto let. Sto let jsem neusnula. Nechte ty hodiny sp\xe1t. Bitte\u2026\u201c"],t.s)
B.bjx=new A.a6(B.xd,B.amh,!1)
B.axv=new A.aO("Ema ud\u011bl\xe1 krok dop\u0159edu a postav\xed se p\u0159ed ostatn\xed. Baronka k n\xed nat\xe1hne ruku. Ale v p\u016fli pohybu se j\xed zav\u0159ou o\u010di. Pomalu se sesune na schod, polo\u017e\xed hlavu na ruku\u2026 a usne. Jej\xed postava zbledne, zpr\u016fhledn\xed a rozplyne se.")
B.aic=s(["\u201eVr\xe1tila se do obrazu?\u201c"],t.s)
B.bk9=new A.a6(B.aY,B.aic,!1)
B.af7=s(["\u201eVypad\xe1 to tak. Ale nev\xedme, na jak dlouho.\u201c"],t.s)
B.bjz=new A.a6(B.aS,B.af7,!1)
B.ag4=s(["\u201eTak si mus\xedme posp\xed\u0161it. Pom\u016f\u017eete star\xe9mu hodin\xe1\u0159i? Je\u0161t\u011b naposledy?\u201c"],t.s)
B.bjR=new A.a6(B.aC,B.ag4,!1)
B.ara=s([B.awC,B.bko,B.axr,B.bkQ,B.awH,B.axG,B.bjx,B.axv,B.bk9,B.bjz,B.bjR],t.a)
B.bmG=new A.cl("story_24",B.ara)
B.awE=new A.aO("\xdalomky se zatav\xed do vosku a pe\u010de\u0165 se rozz\xe1\u0159\xed. Pak praskne a rozlet\xed se na kusy. Pod n\xed se objev\xed cifern\xedk. Ru\u010di\u010dky ukazuj\xed p\u016flnoc. Hodiny se zhluboka nadechnou\u2026 a rozb\u011bhnou se. Po cel\xe9m muzeu se rozezn\xed tik\xe1n\xed v\u0161ech hodin najednou. Ru\u010di\u010dky ute\u010dou od p\u016flnoci, v okn\u011b chodby je vid\u011bt \xfasvit a z\xe1mky v\u0161ech dve\u0159\xed v muzeu cvaknou.")
B.aoa=s(["\u201eSly\u0161\xedte to? Muzeum zase d\xfdch\xe1. Srdce muzea je tajemstv\xed, nikdo ho tu nesm\xed naj\xedt a v\xe1s tak\xe9 ne. Tuhle chodbu zase schov\xe1m. Z\u016fstanu tady a d\xe1m do po\u0159\xe1dku v\u0161echno, co tu baronka provedla. Hodiny u\u017e nikomu nedovol\xedm zastavit. Ani za \u0161\xe1lek levandulov\xe9ho \u010daje.\u201c"],t.s)
B.bkq=new A.a6(B.aC,B.aoa,!1)
B.amS=s(["\u201eA posp\u011b\u0161te si. Baronka te\u010f tvrd\u011b sp\xed. Ale dokud je muzeum zav\u0159en\xe9, m\u016f\u017ee kdykoli vystoupit z obrazu. Otev\u0159ete hlavn\xed dve\u0159e, ne\u017e se vzbud\xed.\u201c"],t.s)
B.bjQ=new A.a6(B.aC,B.amS,!1)
B.aiA=s([B.awE,B.bkq,B.bjQ],t.a)
B.bmz=new A.cl("story_25",B.aiA)
B.axg=new A.aO("Ema ho obejme. Jon\xe1\u0161 mu pod\xe1 ruku. Nela mu vyt\xe1hne pavu\u010dinu z vlas\u016f. Zvenku se ozve motor n\xe1kladn\xedho auta, st\u011bhov\xe1ci p\u0159ijeli pro obraz baronky. D\u011bti b\u011b\u017e\xed zp\xe1tky do vstupn\xed haly. Baronka v obraze sp\xed a usm\xedv\xe1 se. Jen\u017ee hlavn\xed dve\u0159e se po\u0159\xe1d nehnou.")
B.ag8=s(["\u201eZ\xe1mky p\u0159ece cvakly. Tak pro\u010d se ty dve\u0159e neotev\u0159ou?\u201c"],t.s)
B.blh=new A.a6(B.aY,B.ag8,!1)
B.aoU=s(["\u201eH\xe1d\xe1m, \u017ee tohle je posledn\xed past pan\xed baronky.\u201c"],t.s)
B.bjP=new A.a6(B.aM,B.aoU,!1)
B.awQ=new A.aO("Baronka v obraze se zavrt\xed a ze span\xed vzdychne. D\u011bti ztuhnou.")
B.afL=s(["\u201eRychle. A potichu.\u201c"],t.s)
B.blC=new A.a6(B.aM,B.afL,!1)
B.aiq=s([B.axg,B.blh,B.bjP,B.awQ,B.blC],t.a)
B.bne=new A.cl("story_26",B.aiq)
B.axI=new A.aO("Posledn\xed z\xe1str\u010dka cvakne. T\u011b\u017ek\xe1 k\u0159\xeddla dve\u0159\xed se pomalu otev\u0159ou a do haly vtrhne rann\xed sv\u011btlo. Rozlije se po podlaze, po zdech a nakonec dopadne i na obraz.")
B.ajR=s(["\u201eJe otev\u0159eno! Muzeum je otev\u0159en\xe9!\u201c"],t.s)
B.blp=new A.a6(B.aM,B.ajR,!1)
B.air=s(["\u201ePod\xedvejte na obraz. Pan\xed baronce n\u011bjak ztuhl \xfasm\u011bv.\u201c"],t.s)
B.bkD=new A.a6(B.aY,B.air,!1)
B.awa=new A.aO("Tv\xe1\u0159 baronky se pomalu zamra\u010d\xed. U\u017e se nepohne.")
B.ahd=s(["\u201eTak to bychom m\u011bli. A te\u010f honem pry\u010d, ne\u017e n\xe1s tu n\u011bkdo najde.\u201c"],t.s)
B.bje=new A.a6(B.aS,B.ahd,!1)
B.awR=new A.aO("D\u011bti vyklouznou z muzea ve chv\xedli, kdy st\u011bhov\xe1ci vystupuj\xed z auta.")
B.apF=s(["\u201eZvl\xe1dli jsme to!\u201c"],t.s)
B.bk8=new A.a6(B.aM,B.apF,!1)
B.awB=new A.aO("St\u011bhov\xe1ci vejdou do muzea, po chv\xedli vyn\xe1\u0161\xed velk\xfd obraz zabalen\xfd do deky. Jeden roh deky sklouzne.")
B.awx=new A.aO("Baronka Frida von Schlafenberg sice sp\xed, ale tv\xe1\u0159\xed se tak na\u0161tvan\u011b jako je\u0161t\u011b nikdy. V\u0161imnou si toho i st\u011bhov\xe1ci. \u201eNa n\xe1dra\u017e\xed si zvykne,\u201c prohod\xed jeden ze st\u011bhov\xe1k\u016f. Potom, co auto odjede, se v okn\u011b muzea na okam\u017eik objev\xed star\xfd hodin\xe1\u0159 s lampou. K\xfdvne na n\u011b, zamrk\xe1 a zmiz\xed. Z muzea je sly\u0161et tich\xe9, spokojen\xe9 tik\xe1n\xed.")
B.apO=s(["\u201eTohle n\xe1m nikdo neuv\u011b\u0159\xed.\u201c"],t.s)
B.blo=new A.a6(B.aY,B.apO,!1)
B.akg=s([B.axI,B.blp,B.bkD,B.awa,B.bje,B.awR,B.bk8,B.awB,B.awx,B.blo],t.a)
B.bmP=new A.cl("story_27",B.akg)
