B.axe=new A.aO("D\u011bda Bohou\u0161 slav\xed sedmdes\xe1tiny a d\u016fm prask\xe1 ve \u0161vech. Von\xed tu j\xeddlo, cinkaj\xed skleni\u010dky a po\u0159\xe1d n\u011bkdo zvon\xed u dve\u0159\xed. Teta Jarmila \u0161t\xedpe do tv\xe1\u0159\xed ka\u017ed\xe9ho, kdo se nestihne schovat. Str\xfdc Pepa po\u0159\xe1d dokola vypr\xe1v\xed o hypot\xe9k\xe1ch. A d\u011bda spokojen\u011b sed\xed v \u010dele stolu a usm\xedv\xe1 se.")
B.by=new A.kh("klara","assets/images/stories/bohous/story/portrait_klara.webp")
B.ag0=s(["\u201eTohle je ofici\xe1ln\u011b nejnudn\u011bj\u0161\xed oslava na sv\u011bt\u011b. M\xe1m to spo\u010d\xedtan\xe9. Str\xfdc \u0159ekl \u201ahypot\xe9ka\u2018 dvaa\u010dty\u0159icetkr\xe1t.\u201c"],t.s)
B.blv=new A.a6(B.by,B.ag0,!1)
B.b4=new A.kh("tobi","assets/images/stories/bohous/story/portrait_tobi.webp")
B.akM=s(["\u201eTeta m\u011b \u0161t\xedpla p\u011btkr\xe1t. Za chv\xedli budu m\xedt m\xedsto tv\xe1\u0159\xed dv\u011b raj\u010data.\u201c"],t.s)
B.bks=new A.a6(B.b4,B.akM,!1)
B.an2=s(["\u201eDv\u011b mal\xe1 kysel\xe1 raj\u010d\xe1tka.\u201c"],t.s)
B.blt=new A.a6(B.by,B.an2,!1)
B.apb=s(["\u201eJ\xe1 nejsem kysel\xfd!\u201c"],t.s)
B.bjB=new A.a6(B.b4,B.apb,!1)
B.awn=new A.aO("Pod stolem si povzdechne pes Ferda. Nikdo mu zat\xedm neupustil ani drobe\u010dek. Kl\xe1ra k\xfdvne na bratra Tobiho a uk\xe1\u017ee ke schod\u016fm.")
B.aj_=s(["\u201eMiz\xedme.\u201c"],t.s)
B.blM=new A.a6(B.by,B.aj_,!1)
B.awl=new A.aO("Schody vedou na p\u016fdu, kam nikdo nechod\xed.")
B.aoT=s([B.axe,B.blv,B.bks,B.blt,B.bjB,B.awn,B.blM,B.awl],t.a)
B.bn5=new A.cl("story_01",B.aoT)
B.axd=new A.aO("Na p\u016fd\u011b je \u0161ero a v\u0161ude prach. Uprost\u0159ed stoj\xed star\xe1 bedna s velk\xfdm \u010derven\xfdm B.")
B.akr=s(["\u201e\u201aNE-O-TE-V\xcd-RAT!\u2018 A pod t\xedm malink\xfdmi p\xedsmenky: \u201akrom\u011b pr\u016fzkumn\xedk\u016f\u2018.\u201c"],t.s)
B.bjy=new A.a6(B.b4,B.akr,!1)
B.aps=s(["\u201ePr\u016fzkumn\xedci. To jsme p\u0159ece my.\u201c"],t.s)
B.bkp=new A.a6(B.by,B.aps,!1)
B.awv=new A.aO("Bedna m\xe1 z\xe1mek. Ale kl\xed\u010d\u2026 nikde.")
B.ahp=s([B.axd,B.bjy,B.bkp,B.awv],t.a)
B.bmC=new A.cl("story_02",B.ahp)
B.aw7=new A.aO("Z\xe1mek cvakne a v\xedko odsko\u010d\xed. Uvnit\u0159 je hromada pap\xedr\u016f. Najednou se pap\xedry pohnou a vyb\u011bhne z nich mal\xe1 \u0161ed\xe1 my\u0161. Tobi vyp\xedskne. Ferda zak\u0148u\u010d\xed a schov\xe1 se Kl\xe1\u0159e za nohy.")
B.aj1=s(["\u201eFerdo, ty hrdino. Ty se boj\xed\u0161 my\u0161i?\u201c","\u201ePo\u010dkej. Na kalend\xe1\u0159i bylo zakrou\u017ekovan\xe9 jednadvac\xe1t\xe9 z\xe1\u0159\xed. To je p\u0159ece dneska! B jako Bohou\u0161. Tohle je d\u011bdova bedna!\u201c"],t.s)
B.bki=new A.a6(B.by,B.aj1,!1)
B.axF=new A.aO("My\u0161 si z pap\xedr\u016f ud\u011blala pel\xed\u0161ek. Tobi je opatrn\u011b p\u0159eb\xedr\xe1 a najde \xfatr\u017eek s nakreslen\xfdm praporkem.")
B.ajb=s(["\u201eKl\xe1ro\u2026 to je mapa k pokladu!\u201c"],t.s)
B.bjK=new A.a6(B.b4,B.ajb,!1)
B.aqS=s(["\u201eNebo n\xe1kupn\xed seznam.\u201c"],t.s)
B.bkA=new A.a6(B.by,B.aqS,!1)
B.aaU=s(["\u201eNa n\xe1kupn\xed seznam se praporky nekresl\xed!\u201c"],t.s)
B.biZ=new A.a6(B.b4,B.aaU,!1)
B.ahJ=s(["\u201eA na mapu k pokladu se kresl\xed k\u0159\xed\u017eek. Vid\xed\u0161 tu n\u011bjak\xfd?\u201c"],t.s)
B.biw=new A.a6(B.by,B.ahJ,!1)
B.axJ=new A.aO("Na \xfatr\u017eku \u017e\xe1dn\xfd k\u0159\xed\u017eek nen\xed. Ale \xfatr\u017ek\u016f je v bedn\u011b spousta.")
B.ap5=s([B.aw7,B.bki,B.axF,B.bjK,B.bkA,B.biZ,B.biw,B.axJ],t.a)
B.bmH=new A.cl("story_03",B.ap5)
B.aqi=s(["\u201eMapa kapit\xe1na Bohou\u0161e. Z roku 1964.\u201c"],t.s)
B.bj9=new A.a6(B.b4,B.aqi,!1)
B.ao7=s(["\u201e\u201aPevnost.\u2018 \u201aPozor! Dinosau\u0159i!\u2018 \u201aBa\u017eina smrti.\u2018\u201c","\u201eNo, to je teda zahrada.\u201c"],t.s)
B.bkE=new A.a6(B.by,B.ao7,!1)
B.apr=s(["\u201eDinosau\u0159i! D\u011bda m\u011bl na zahrad\u011b dinosaury?\u201c"],t.s)
B.bj0=new A.a6(B.b4,B.apr,!1)
B.acc=s(["\u201eJo, a j\xe1 m\xe1m pod postel\xed draka.\u201c"],t.s)
B.bkn=new A.a6(B.by,B.acc,!1)
B.adu=s(["\u201eJen tu mapu ta my\u0161 celou prokousala. Jsou v n\xed sam\xe9 d\xedry.\u201c"],t.s)
B.bkt=new A.a6(B.b4,B.adu,!1)
B.ab5=s(["\u201ePevnost\u2026 Na zahrad\u011b ale \u017e\xe1dn\xe1 pevnost nen\xed. Je tam jen gar\xe1\u017e.\u201c"],t.s)
B.bjW=new A.a6(B.by,B.ab5,!1)
B.ahG=s(["\u201ePevnost je p\u0159ece ka\u017ed\xe1 skr\xfd\u0161. Stan z deky. Sk\u0159\xed\u0148. Nebo\u2026 star\xe1 k\u016flna!\u201c"],t.s)
B.bkz=new A.a6(B.b4,B.ahG,!1)
B.ajG=s(["\u201eTobi, ty jsi g\xe9nius! Babi\u010dka jednou \u0159\xedkala, \u017ee gar\xe1\u017e b\xfdvala k\u016flna.\u201c"],t.s)
B.blJ=new A.a6(B.by,B.ajG,!1)
B.axp=new A.aO("Tobi se za\u010derven\xe1. Takovou pochvalu od sestry je\u0161t\u011b nikdy nedostal.")
B.aw5=new A.aO("D\u011bti se propl\xed\u017e\xed do gar\xe1\u017ee. Z\u016fstala v n\xed star\xe1 kamenn\xe1 ze\u010f a tlust\xfd tr\xe1m z doby, kdy tu st\xe1la k\u016flna.")
B.adf=s(["\u201eKl\xe1ro, na tom tr\xe1mu n\u011bco je.\u201c"],t.s)
B.bj8=new A.a6(B.b4,B.adf,!1)
B.akk=s(["\u201eVypad\xe1 to jako n\u011bjak\xe9 tajn\xe9 p\xedsmo. Kapit\xe1n Bohou\u0161 m\u011bl tajn\xe9 p\xedsmo?\u201c"],t.s)
B.bke=new A.a6(B.by,B.akk,!1)
B.aib=s([B.bj9,B.bkE,B.bj0,B.bkn,B.bkt,B.bjW,B.bkz,B.blJ,B.axp,B.aw5,B.bj8,B.bke],t.a)
B.bmy=new A.cl("story_04",B.aib)
B.awh=new A.aO("Ze\u010f se zachv\u011bje, k\xe1men zajede dovnit\u0159 a ze skr\xfd\u0161e se vysune plechov\xe1 krabi\u010dka. Uvnit\u0159 le\u017e\xed kompas.")
B.aqm=s(["\u201eTo je skute\u010dn\xfd kapit\xe1nsk\xfd kompas!\u201c"],t.s)
B.bis=new A.a6(B.b4,B.aqm,!1)
B.axL=new A.aO("Pod kompasem je star\xe1 \u010dernob\xedl\xe1 fotka. Mal\xfd kluk s lopatkou u studny a \u010derven\xfd k\u0159\xed\u017eek. Na rubu je n\u011bco naps\xe1no.")
B.ak4=s(["\u201e\u201aTady jsem ho zakopal. B.\u2018\u201c"],t.s)
B.biU=new A.a6(B.by,B.ak4,!1)
B.ajf=s(["\u201eTen kluk\u2026 m\xe1 na hlav\u011b stejn\xfd chom\xe1\u010dek jako d\u011bda.\u201c"],t.s)
B.bl2=new A.a6(B.b4,B.ajf,!1)
B.apm=s(["\u201eProto\u017ee to je d\u011bda, Tobi.\u201c"],t.s)
B.blf=new A.a6(B.by,B.apm,!1)
B.arc=s([B.awh,B.bis,B.axL,B.biU,B.bl2,B.blf],t.a)
B.bn4=new A.cl("story_05",B.arc)
B.axB=new A.aO("Studna na zahrad\u011b stoj\xed dodnes. Kl\xe1ra se k n\xed rozb\u011bhne, ale Tobi ji chyt\xed za ruk\xe1v.")
B.ad8=s(["\u201e\u010c\xe1ra vede p\u0159es v\u0161echny praporky. Kapit\xe1n by si to nezkracoval.\u201c"],t.s)
B.bkY=new A.a6(B.b4,B.ad8,!1)
B.ax8=new A.aO("Dal\u0161\xed praporek je u n\xe1pisu \u201ePozor! Dinosau\u0159i!\u201c. Dnes tam le\u017e\xed jen star\xe1 betonov\xe1 deska pod hromadou list\xed.")
B.amP=s(["\u201eCo kdy\u017e tu je\u0161t\u011b n\u011bjak\xfd je?\u201c"],t.s)
B.bkF=new A.a6(B.b4,B.amP,!1)
B.amX=s(["\u201e\u017d\xe1dn\xed dinosau\u0159i. Babi\u010dka \u0159\xedkala, \u017ee tady b\xfdval kurn\xedk.\u201c"],t.s)
B.bkK=new A.a6(B.by,B.amX,!1)
B.ad4=s(["\u201eSlepice? Tak to d\u011bda trochu p\u0159eh\xe1n\u011bl.\u201c"],t.s)
B.bkG=new A.a6(B.b4,B.ad4,!1)
B.apR=s(["\u201eVlastn\u011b ani ne. Slepice jsou potomci dinosaur\u016f.\u201c"],t.s)
B.blj=new A.a6(B.by,B.apR,!1)
B.aeE=s([B.axB,B.bkY,B.ax8,B.bkF,B.bkK,B.bkG,B.blj],t.a)
B.bmW=new A.cl("story_06",B.aeE)
B.ad9=s(["\u201eTak\u017ee kohout Rex nah\xe1n\u011bl mal\xe9ho d\u011bdu!\u201c"],t.s)
B.biH=new A.a6(B.by,B.ad9,!1)
B.apc=s(["\u201eD\u011bda v\u017edycky vypr\xe1v\xed, jak lovil dinosaury. A p\u0159itom dinosaurus lovil jeho!\u201c"],t.s)
B.bkl=new A.a6(B.b4,B.apc,!1)
B.awG=new A.aO("Ferda nastra\u017e\xed u\u0161i. N\u011bco uc\xedt\xed a rozb\u011bhne se. D\u011bti se ho sna\u017e\xed chytit, ale on se \u017eene p\u0159es zahradu k m\xedstu, kter\xe9mu mapa \u0159\xedk\xe1 Ba\u017eina smrti. Ferda stoj\xed na star\xe9 fo\u0161n\u011b v bahn\u011b, vrt\xed ocasem a m\xed\u0159\xed ke kompostu.")
B.aeX=s(["\u201eFerdo, k noze!\u201c"],t.s)
B.biL=new A.a6(B.by,B.aeX,!1)
B.alX=s(["\u201eMus\xedme ho odtamtud n\u011bjak dostat.\u201c"],t.s)
B.bjV=new A.a6(B.b4,B.alX,!1)
B.am3=s([B.biH,B.bkl,B.awG,B.biL,B.bjV],t.a)
B.bmM=new A.cl("story_07",B.am3)
B.axo=new A.aO("Ferda ch\u0148apne kost a sko\u010d\xed s n\xed rovnou do kompostu. Pak vylet\xed ven a cel\xfd u\u0161mudlan\xfd uh\xe1n\xed k domu.")
B.apK=s(["\u201eNe, ne, ne, ne\u2026\u201c"],t.s)
B.biX=new A.a6(B.by,B.apK,!1)
B.axb=new A.aO("Z domu se ozve \u0159in\u010den\xed a k\u0159ik. Za chvilku se Ferda p\u0159i\u0159\xedt\xed zp\xe1tky. Spokojen\xfd, umazan\xfd a se str\xfdcovou kravatou v zubech.")
B.aaR=s(["\u201eAspo\u0148 u\u017e nebude vypr\xe1v\u011bt o hypot\xe9k\xe1ch. Te\u010f bude vypr\xe1v\u011bt o kravat\u011b.\u201c"],t.s)
B.bjm=new A.a6(B.b4,B.aaR,!1)
B.aws=new A.aO("U studny Tobi zvedne fotku a porovn\xe1v\xe1. Studna je po\u0159\xe1d na stejn\xe9m m\xedst\u011b. Jen mal\xfd stromek, u kter\xe9ho stoj\xed mal\xfd Bohou\u0161, tu nikde nen\xed.")
B.agO=s(["\u201e\u201aTady jsem ho zakopal.\u2018 Jen\u017ee kde je to \u201atady\u2018?\u201c"],t.s)
B.biA=new A.a6(B.b4,B.agO,!1)
B.ady=s([B.axo,B.biX,B.axb,B.bjm,B.aws,B.biA],t.a)
B.bn9=new A.cl("story_08",B.ady)
B.awg=new A.aO("Kol\xedk cinkne o n\u011bco tvrd\xe9ho. P\u0159\xedmo mezi ko\u0159eny obrovsk\xe9 jablon\u011b.")
B.aiG=s(["\u201eKl\xe1ro. Ten mal\xfd stromek\u2026 to je ta ob\u0159\xed jablo\u0148?\u201c"],t.s)
B.bir=new A.a6(B.b4,B.aiG,!1)
B.aka=s(["\u201e\u0160edes\xe1t let, Tobi. Mal\xe9 stromky za takovou dobu trochu vyrostou, v\xed\u0161?\u201c"],t.s)
B.bjU=new A.a6(B.by,B.aka,!1)
B.ad1=s(["\u201eTak\u017ee d\u011bda byl taky jednou mal\xfd stromek.\u201c"],t.s)
B.bkS=new A.a6(B.b4,B.ad1,!1)
B.avZ=new A.aO("Kl\xe1ra p\u0159inese z gar\xe1\u017ee dv\u011b lopatky.")
B.ahA=s(["\u201eJ\xe1 prvn\xed!\u201c"],t.s)
B.bjX=new A.a6(B.by,B.ahA,!1)
B.aoc=s(["\u201eNe, j\xe1!\u201c"],t.s)
B.blg=new A.a6(B.b4,B.aoc,!1)
B.awz=new A.aO("Kopou oba najednou a Ferda kope s nimi. Pak lopatka naraz\xed na plechovou krabici. Ko\u0159eny jablon\u011b ji ale celou obrostly.")
B.ap9=s([B.awg,B.bir,B.bjU,B.bkS,B.avZ,B.bjX,B.blg,B.awz],t.a)
B.bnb=new A.cl("story_09",B.ap9)
B.axu=new A.aO("Krabice je kone\u010dn\u011b voln\xe1. Je ale tak t\u011b\u017ek\xe1, \u017ee s n\xed d\u011bti ani nepohnou.")
B.f8=new A.kh("bohous","assets/images/stories/bohous/story/portrait_bohous.webp")
B.aor=s(["\u201eCopak to tu kopete, pr\u016fzkumn\xedci? Zlato? Nebo snad hled\xe1te krtky?\u201c"],t.s)
B.bjZ=new A.a6(B.f8,B.aor,!1)
B.axm=new A.aO("Nad j\xe1mou stoj\xed d\u011bda. P\u0159i\u0161el se pod\xedvat, jakou neplechu zase prov\xe1d\xed Ferda. Pak si v\u0161imne krabice a zmlkne.")
B.anQ=s(["\u201eTo snad\u2026 to nen\xed mo\u017en\xe9.\u201c"],t.s)
B.bjv=new A.a6(B.f8,B.anQ,!1)
B.awr=new A.aO("D\u011bda si klekne do hl\xedny ve sv\xfdch sv\xe1te\u010dn\xedch kalhot\xe1ch a pohlad\xed rezav\xe9 v\xedko krabice.")
B.ahK=s([B.axu,B.bjZ,B.axm,B.bjv,B.awr],t.a)
B.bn3=new A.cl("story_10",B.ahK)
B.anN=s(["\u201eBylo mi deset. T\xe1ta vykopal j\xe1mu a j\xe1 do krabice dal v\u0161echno, co jsem m\u011bl nejrad\u0161i. A pak jsem mu \u0159ekl: \u201aTati, otev\u0159eme ji spolu. Za deset let. Slib to!\u2018\u201c","\u201eA t\xe1ta sl\xedbil. Napsali jsme to na pap\xedr a oba se podepsali. Jen\u017ee za deset let jsem byl na vojn\u011b, pak p\u0159i\u0161la svatba, d\u011bti\u2026 a na kapsli jsme \xfapln\u011b zapomn\u011bli.\u201c"],t.s)
B.bkf=new A.a6(B.f8,B.anN,!1)
B.anW=s(["\u201eTak ji otev\u0159i te\u010f, d\u011bdo. S n\xe1mi.\u201c"],t.s)
B.blE=new A.a6(B.b4,B.anW,!1)
B.awd=new A.aO("Na v\xedku nejsou \u017e\xe1dn\xe9 z\xe1mky, jen vyryt\xe1 p\xedsmenka. Kl\xe1ra polo\u017e\xed vedle kapsle kompas. Tobi rozlo\u017e\xed mapu.")
B.acM=s(["\u201eJen \u0161koda t\u011bch d\u011br od my\u0161i.\u201c"],t.s)
B.blB=new A.a6(B.b4,B.acM,!1)
B.aqx=s(["\u201eMy\u0161? Kdepak! Ty d\xedry vy\u0159\xedzl t\xe1ta. Ta mapa je kl\xed\u010d ke kapsli.\u201c","\u201eJen\u017ee jak se s n\xed otev\xedr\xe1\u2026 to si u\u017e nepamatuju.\u201c"],t.s)
B.bim=new A.a6(B.f8,B.aqx,!1)
B.ajI=s([B.bkf,B.blE,B.awd,B.blB,B.bim],t.a)
B.bmS=new A.cl("story_11",B.ajI)
B.awy=new A.aO("Pod dvojit\xfdm dnem le\u017e\xed kapesn\xed hodinky.")
B.an0=s(["\u201eDvojit\xe9 dno? O tom jsem v\u016fbec nev\u011bd\u011bl! To mi t\xe1ta ne\u0159ekl.\u201c"],t.s)
B.bjC=new A.a6(B.f8,B.an0,!1)
B.awV=new A.aO("D\u011bda vezme hodinky do dlan\u011b a dlouze se na n\u011b d\xedv\xe1.")
B.akC=s(["\u201eT\xe1tovy hodinky. Myslel jsem, \u017ee se d\xe1vno ztratily.\u201c"],t.s)
B.bjw=new A.a6(B.f8,B.akC,!1)
B.axt=new A.aO("Pod hodinkami le\u017e\xed slo\u017een\xfd l\xedste\u010dek.")
B.ar1=s(["\u201e\u201aMil\xfd Bohou\u0161i, dnes je Ti dvacet let. Tyhle hodinky jsem dostal od sv\xe9ho t\xe1ty, kdy\u017e mi bylo dvacet. Te\u010f jsou Tvoje. Jsem na Tebe py\u0161n\xfd. T\xe1ta.\u2018\u201c"],t.s)
B.bkw=new A.a6(B.f8,B.ar1,!1)
B.aw1=new A.aO("Chv\xedli je ticho. D\u011bda nat\xe1hne hodinky a po \u0161edes\xe1ti letech se znovu ozve: tik, tak, tik, tak.")
