B.byg=new A.bq(9,"odjede","sfx_story_truck_leave",null,1)
B.byI=new A.bq(9,"tik\xe1n\xed","sfx_story_soft_ticking",null,1)
B.aku=s([B.byE,B.byn,B.byg,B.byI],t.c)
B.b3H=new A.e(0,0,170.20355132091814,311.82330012992634)
B.b4r=new A.e(120,0,311.85794716327416,170.20355132091814)
B.b1c=new A.e(129.9,129.9,311.79692507579034,311.79692507579034)
B.kP=s([B.b3H,B.b4r,B.b1c],t.u)
B.awX=new A.aO("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.cC=new A.kh("marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.adz=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.biY=new A.a6(B.cC,B.adz,!1)
B.bN=new A.kh("karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.ai5=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.blz=new A.a6(B.bN,B.ai5,!1)
B.anI=s([B.awX,B.biY,B.blz],t.a)
B.bn7=new A.cl("story_00_intro",B.anI)
B.awf=new A.aO("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.aem=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.bj7=new A.a6(B.cC,B.aem,!1)
B.ax3=new A.aO("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.aew=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.bj3=new A.a6(B.bN,B.aew,!1)
B.cK=new A.kh("tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.ap_=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.blk=new A.a6(B.cK,B.ap_,!1)
B.aeS=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.bkC=new A.a6(B.cC,B.aeS,!1)
B.anV=s([B.awf,B.bj7,B.ax3,B.bj3,B.blk,B.bkC],t.a)
B.bmI=new A.cl("story_01a_clubhouse_arrival",B.anV)
B.agn=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.bjM=new A.a6(B.cC,B.agn,!1)
B.ait=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.bkJ=new A.a6(B.cK,B.ait,!1)
B.ace=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.bl4=new A.a6(B.bN,B.ace,!1)
B.aer=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.bl0=new A.a6(B.cK,B.aer,!1)
B.adC=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.bk3=new A.a6(B.bN,B.adC,!1)
B.aaY=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.biI=new A.a6(B.cC,B.aaY,!1)
B.alj=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.blF=new A.a6(B.bN,B.alj,!1)
B.aqN=s([B.bjM,B.bkJ,B.bl4,B.bl0,B.bk3,B.biI,B.blF],t.a)
B.bmB=new A.cl("story_01b_legend_and_time",B.aqN)
B.axH=new A.aO("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.agv=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.bjT=new A.a6(B.bN,B.agv,!1)
B.afA=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.blQ=new A.a6(B.cK,B.afA,!1)
B.aq0=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.bl_=new A.a6(B.bN,B.aq0,!1)
B.akJ=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.biC=new A.a6(B.cK,B.akJ,!1)
B.adh=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.biF=new A.a6(B.cC,B.adh,!1)
B.aj4=s([B.axH,B.bjT,B.blQ,B.bl_,B.biC,B.biF],t.a)
B.bmA=new A.cl("story_02_torn_map",B.aj4)
B.acf=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.bjS=new A.a6(B.cC,B.acf,!1)
B.alQ=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.blq=new A.a6(B.bN,B.alQ,!1)
B.awJ=new A.aO("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.ap4=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.bls=new A.a6(B.cK,B.ap4,!1)
B.apq=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.blx=new A.a6(B.bN,B.apq,!1)
B.ak2=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.bj5=new A.a6(B.cC,B.ak2,!1)
B.acG=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.bjJ=new A.a6(B.bN,B.acG,!1)
B.acO=s([B.bjS,B.blq,B.awJ,B.bls,B.blx,B.bj5,B.bjJ],t.a)
B.bmD=new A.cl("story_03_founders_trail",B.acO)
B.awj=new A.aO("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.af9=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.blK=new A.a6(B.bN,B.af9,!1)
B.alb=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.bkU=new A.a6(B.cK,B.alb,!1)
B.aoJ=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.bl5=new A.a6(B.bN,B.aoJ,!1)
B.agQ=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.bkL=new A.a6(B.cC,B.agQ,!1)
B.abJ=s([B.awj,B.blK,B.bkU,B.bl5,B.bkL],t.a)
B.bmx=new A.cl("story_04_flowers_in_mud",B.abJ)
B.awO=new A.aO("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.ae3=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.bjg=new A.a6(B.bN,B.ae3,!1)
B.ab3=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.bkB=new A.a6(B.cK,B.ab3,!1)
B.ahs=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.blV=new A.a6(B.bN,B.ahs,!1)
B.aqY=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.bjI=new A.a6(B.cC,B.aqY,!1)
B.akA=s([B.awO,B.bjg,B.bkB,B.blV,B.bjI],t.a)
B.bnj=new A.cl("story_05_old_oak",B.akA)
B.awK=new A.aO("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.alV=s(["\u201eCo se to stalo?\u201c"],t.s)
B.bly=new A.a6(B.bN,B.alV,!1)
B.ahf=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.bjG=new A.a6(B.cC,B.ahf,!1)
B.aec=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.bjE=new A.a6(B.bN,B.aec,!1)
B.ai8=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.bkO=new A.a6(B.cC,B.ai8,!1)
B.awq=new A.aO("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.ahw=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.bkv=new A.a6(B.cK,B.ahw,!1)
B.aqD=s([B.awK,B.bly,B.bjG,B.bjE,B.bkO,B.awq,B.bkv],t.a)
B.bmE=new A.cl("story_06_waterfall_chest",B.aqD)
B.ax2=new A.aO("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.afF=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.blX=new A.a6(B.cK,B.afF,!1)
B.aqw=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.bjH=new A.a6(B.cC,B.aqw,!1)
B.axw=new A.aO("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.aqL=s([B.ax2,B.blX,B.bjH,B.axw],t.a)
B.bn_=new A.cl("story_07_scroll",B.aqL)
B.aw4=new A.aO("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.aox=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.blL=new A.a6(B.bN,B.aox,!1)
B.amF=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
B.biq=new A.a6(B.cK,B.amF,!1)
B.aeo=s(["\u201eA pro\u010d to nenapsali rovnou na dve\u0159e?\u201c"],t.s)
B.biy=new A.a6(B.bN,B.aeo,!1)
B.aiN=s(["\u201eProto\u017ee by t\u011b nebavilo to hledat.\u201c"],t.s)
B.bjh=new A.a6(B.cK,B.aiN,!1)
B.ajN=s(["\u201eTrp\u011blivost \u2026 ta mi nikdy moc ne\u0161la.\u201c"],t.s)
B.blu=new A.a6(B.cC,B.ajN,!1)
B.akB=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.bil=new A.a6(B.cK,B.akB,!1)
B.akw=s(["\u201eJ\xe1 \u010dek\xe1m na dort a trp\u011blivost m\xe1m.\u201c"],t.s)
B.bjj=new A.a6(B.bN,B.akw,!1)
B.ahu=s(["\u201eTo nen\xed trp\u011blivost, K\xe1jo. To je hlad.\u201c"],t.s)
B.bkd=new A.a6(B.cK,B.ahu,!1)
B.adx=s(["\u201eA tob\u011b se zkou\u0161ka povedla. Bez tebe bychom to do z\xe1padu nestihli.\u201c"],t.s)
B.bj2=new A.a6(B.cC,B.adx,!1)
B.ad2=s([B.aw4,B.blL,B.biq,B.biy,B.bjh,B.blu,B.bil,B.bjj,B.bkd,B.bj2],t.a)
B.bmL=new A.cl("story_08_ending_dialogue",B.ad2)
B.akK=s([B.bn7,B.bmI,B.bmB,B.bmA,B.bmD,B.bmx,B.bnj,B.bmE,B.bn_,B.bmL],t.WD)
